#!/bin/sh
# Postprovision hook (macOS/Linux): writes the app .env from azd outputs.
# azd exposes Bicep outputs as environment variables to this hook.
set -e
ENV_PATH="$(dirname "$0")/../.env"

cat > "$ENV_PATH" <<EOF
# Generated by 'azd up' (scripts/write-dotenv.sh). Do not commit.
FOUNDRY_PROJECT_ENDPOINT=${FOUNDRY_PROJECT_ENDPOINT}
CHAT_DEPLOYMENT=${CHAT_DEPLOYMENT}
MULTIMODAL_DEPLOYMENT=${MULTIMODAL_DEPLOYMENT}
IMAGE_DEPLOYMENT=${IMAGE_DEPLOYMENT}
EMBEDDING_DEPLOYMENT=${EMBEDDING_DEPLOYMENT}
AGENT_NAME=wealth-concierge
SPEECH_REGION=${SPEECH_REGION}
SPEECH_RESOURCE_ID=${SPEECH_RESOURCE_ID}
CONTENT_UNDERSTANDING_ENDPOINT=${CONTENT_UNDERSTANDING_ENDPOINT}
CONTENT_UNDERSTANDING_API_VERSION=2025-11-01
LANGUAGE_ENDPOINT=${LANGUAGE_ENDPOINT}

# OPTIONAL Module 4 demos (Parts B & C). VOICE_LIVE_MODEL is provisioned;
# SPEECH_MCP_URL is a preview Foundry Tools endpoint you set manually.
VOICE_LIVE_MODEL=${VOICE_LIVE_MODEL}
VOICE_LIVE_ENDPOINT=
SPEECH_MCP_URL=
EOF

echo "Wrote $ENV_PATH"
